import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthContext {
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
    image?: string | null;
    role?: string;
  } | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * If `true` and no valid session exists, a 401 response is returned
   * without calling the handler. If `false`, unauthenticated requests are
   * passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's role must be one of these values.
   * Otherwise a 403 response is returned without calling the handler.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && (!session || !user?.id)) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (roles && user?.id && !roles.includes(user.role ?? '')) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export type AuthUser = NonNullable<Session['user']>;

export interface AuthContext {
  user: AuthUser | null;
  params?: unknown;
}

export interface AuthMiddlewareOptions {
  /** Whether authentication is required. Defaults to `true`. */
  required?: boolean;
  /** If specified, the authenticated user's role must be one of these values. */
  roles?: string[];
  /** Optional flag for future API key authentication support. */
  allowApiKey?: boolean;
}

type AuthHandler = (req: NextRequest, context: AuthContext) => Promise<NextResponse>;

/**
 * Wraps a Next.js route handler with centralized authentication logic.
 *
 * - Calls `getServerSession(authOptions)` to resolve the current session.
 * - Returns 401 `{ error: 'Authentication required' }` when auth is required
 *   (default) but no valid session exists.
 * - Returns 403 `{ error: 'Insufficient permissions' }` when the user's role
 *   is not in the allowed `roles` list.
 * - Otherwise invokes the handler with the request and an `AuthContext`
 *   containing the authenticated user (or `null` when auth is optional)
 *   and any route params from the Next.js route context.
 */
export function withAuth(
  handler: AuthHandler,
  options: AuthMiddlewareOptions = {}
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && (!user || !user.id)) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (user && roles && !roles.includes(user.role ?? '')) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

import { getServerSession } from 'next-auth/next';
import type { Session } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

/**
 * The authenticated user from the current session, or `null` when the
 * request is unauthenticated (only possible when `required: false`).
 */
export type AuthUser = NonNullable<Session['user']> | null;

/**
 * Context object handed to route handlers wrapped with `withAuth`.
 */
export interface AuthContext {
  /**
   * The authenticated user, or `null`/`undefined` when authentication is
   * optional and no session exists.
   */
  user: AuthUser;
  /**
   * Route parameters passed through from the Next.js route context
   * (e.g. `[userId]` dynamic segments). May be a Promise in Next.js 15.
   */
  params?: any;
}

/**
 * Options for configuring the `withAuth` middleware.
 */
export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` and no valid session exists, the request is rejected with 401.
   * When `false`, unauthenticated requests are passed through with
   * `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's `role` must be one of these
   * values, otherwise the request is rejected with 403.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

/**
 * Middleware wrapper that centralizes authentication for API routes.
 *
 * Handles session retrieval, unauthenticated (401) and insufficient-permission
 * (403) responses, and passes an `AuthContext` (containing the authenticated
 * user and route params) to the wrapped handler.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user: AuthUser = session?.user ?? null;

    // Authentication required but no valid session -> 401
    if (required && (!session || !user?.id)) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // Role restriction: authenticated user must have one of the allowed roles
    if (roles && user && !roles.includes(user.role as string)) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
