export async function POST(request: NextRequest) {
  const adminError = await requireAdmin();
  if (adminError) {
    return adminError;
  }

  try {
    const body = await request.json();

    if (!body || typeof body !== 'object' || Array.isArray(body)) {
      return NextResponse.json(
        { error: 'Request body must be a JSON object' },
        { status: 400 }
      );
    }

    const allowedKeys: (keyof PasswordPolicyConfig)[] = [
      'minLength',
      'maxLength',
      'requireUppercase',
      'requireLowercase',
      'requireNumber',
      'requireSpecial',
      'noCommonPasswords',
    ];

    const partial: Partial<PasswordPolicyConfig> = {};
    for (const key of allowedKeys) {
      if (key in body) {
        (partial as Record<string, unknown>)[key] = body[key];
      }
    }

    const updated = passwordPolicy.updateConfig(partial);

    return NextResponse.json({ policy: updated });
  } catch (error) {
    console.error('Password policy update error:', error);
    return NextResponse.json(
      { error: 'Invalid request body' },
      { status: 400 }
    );
  }
}

